 209→    fn resolver_has_default_max_depth() {
 210→        let resolver = ExtendsResolver::new();
 211→        assert_eq!(resolver.max_depth(), 10);
 212→    }
 213→
 214→    #[test]
 215→    fn resolver_custom_max_depth() {
 216→        let resolver = ExtendsResolver::with_max_depth(5);
 217→        assert_eq!(resolver.max_depth(), 5);
 218→    }
