/// Convert a TOML value into a `serde_yaml::Value` for use in the
/// merge pipeline.
fn toml_to_yaml_value(toml_val: toml::Value) -> Result<serde_yaml::Value> {
    // Serialize the TOML value to a generic JSON value, then convert
    // to YAML value. Both implement Serialize/Deserialize via serde,
    // so the round-trip is lossless for the types we care about.
    let json = serde_json::to_value(toml_val).map_err(|e| BivvyError::ConfigParseError {
        path: PathBuf::from("<toml-conversion>"),
        message: format!("Failed to convert TOML to intermediate value: {e}"),
    })?;
    serde_yaml::to_value(json).map_err(|e| BivvyError::ConfigParseError {
        path: PathBuf::from("<toml-conversion>"),
        message: format!("Failed to convert to YAML value: {e}"),
    })
}

