 15→/// Check whether a path has a `.toml` extension.
 16→pub fn is_toml_file(path: &Path) -> bool {
 17→    path.extension().is_some_and(|ext| ext == "toml")
 18→}
 19→
 20→/// Find the first existing config file with the given base name,
 21→/// preferring `.toml` over `.yml`.
 22→fn find_first_existing(dir: &Path, base_name: &str) -> Option<PathBuf> {
 23→    let toml_path = dir.join(format!("{base_name}.toml"));
 24→    if toml_path.exists() {
 25→        return Some(toml_path);
 26→    }
 27→    let yml_path = dir.join(format!("{base_name}.yml"));
 28→    if yml_path.exists() {
 29→        return Some(yml_path);
 30→    }
 31→    None
 32→}
 33→
 34→/// Paths to configuration files in priority order (later overrides earlier).
 35→///
